        ///   </para>
        ///   <para>
        ///     This function marks the event instance to be released. Event instances marked for release are destroyed
        ///     by the asynchronous update when they are in the stopped state (FMOD_STUDIO_PLAYBACK_STOPPED).
        ///   </para>
        ///   <para>
        ///     Generally it is a best practice to release event instances immediately after calling
        ///     Studio::EventInstance::start, unless you want to play the event instance multiple times or explicitly
        ///     stop it and start it again later. It is possible to interact with the instance after falling
        ///     <c>release()</c>, however if the sound has stopped <c>ERR_INVALID_HANDLE</c> will be returned.
        ///   </para>
        ///   <para>
        ///     <b>See Also:</b> Studio::EventInstance::stop, Studio::EventInstance::getPlaybackState
        ///   </para>
        ///   <para>
        ///     <see href="https://www.fmod.com/docs/2.03/api/studio-api-eventinstance.html#studio_eventinstance_release">Studio::EventInstance::release</see>
        ///   </para>
        /// </summary>
        public static Result TryRelease(this EventInstance eventInstance) =>
            PInvoke.EventInstanceRelease(eventInstance);

